// Only the authorized Node outbox worker may call this Header Auth webhook.
// An API caller's consent flag is NOT independent authorization evidence.
const b=$input.first().json.body??{};
function string(v,name,max) {
  if(typeof v!=='string'||!v.trim()||v.length>max)throw new Error('Invalid '+name);
  return v.trim();
}
const ticketId=string(b.ticketId,'ticketId',36);
if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(ticketId))throw new Error('Invalid ticket ID');
if(b.agentKey!=='ancfz'||b.consent!==true)throw new Error('Node-authorized ANCFZ consent required');
// Allow existing Node facts (camelCase), or the exact Apex REST field names.
const lead={
  Name:string(b.name??b.Name,'Name',120),
  Company:string(b.company??b.Company,'Company',255),
  Phone:string(b.phone??b.Phone,'Phone',40),
  Email:string(b.email??b.Email,'Email',254),
  Description:string(b.description??b.Description??b.enquiry,'Description',4000),
};
if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.Email))throw new Error('Invalid Email');
if(!/^\+?[0-9 ()-]{7,40}$/.test(lead.Phone))throw new Error('Invalid Phone');
return [{json:{ticketId,lead}}];

// The custom Apex REST success schema was not included in the sample.
// Only treat a real Salesforce Lead ID returned by the endpoint as verified.
// Do not invent an ID or claim creation on a generic HTTP 200.
const raw=$input.first().json;
const body=(raw!==null&&typeof raw==='object'&&!Array.isArray(raw))?raw:{raw};
const data=(body.data!==null&&typeof body.data==='object'&&!Array.isArray(body.data))?body.data:body;
const candidate=data.leadId??data.LeadId??data.Id??data.id;
const leadId=typeof candidate==='string'&&/^00Q(?:[A-Za-z0-9]{12}|[A-Za-z0-9]{15})$/.test(candidate)?candidate:null;
const negative=body.success===false||data.success===false||body.error===true||data.error===true;
if(negative)throw new Error('Salesforce Apex REST reported failure');
const ticketId=$('Validate ANCFZ Lead').first().json.ticketId;
return [{json:{status:leadId?'verified_completed':'provider_acknowledged_unverified',
  provider:'salesforce_apex_rest',ticketId,leadId,verified:Boolean(leadId)}}];
